INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch01$A$batch01$, $batch01$The examples are physicians, attorneys, physicists, and engineers; they support the premise about professional evaluations. Even if that premise were true across professions, the transfer to school exams would still need a justification.$batch01$), ($batch01$B$batch01$, $batch01$The recommendation is not premised on raising students' scores. It is premised on making exams resemble professional evaluations. No score increase is required for that rationale.$batch01$), ($batch01$C$batch01$, $batch01$Professionals' past exams without books do not settle what tools present-day students should have. The analogy hinges on what current exams are trying to measure.$batch01$), ($batch01$D$batch01$, $batch01$Professionals' longer study might make their use of books different, but the argument does not depend on equal levels of subject mastery. The sharper objection is that the *purpose of evaluation* may differ. Even equally trained people could be tested for different purposes.$batch01$), ($batch01$E$batch01$, $batch01$If professional evaluations test realistic practice and school exams test independent mastery, their different purposes explain why one allows references and the other may not. The analogy needs similarity in the respect that matters for the proposed policy.$batch01$)) v(letter,body) WHERE q.qid=$batch01$PT107-S4-Q25$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id) ON CONFLICT DO NOTHING;
